// Minimize Window / Hide Screen
const minimizeWindowBtn = document.getElementById('minimizeWindowBtn');
if (minimizeWindowBtn) {
  let isMinimizing = false;

  const restoreScreen = () => {
    isMinimizing = false;
    document.body.classList.remove('screen-disappearing');
  };

  minimizeWindowBtn.addEventListener('click', async (e) => {
    e.preventDefault();
    if (isMinimizing) return;
    isMinimizing = true;
    document.body.classList.add('screen-disappearing');

    try {
      const res = await fetch('/v1/desktop/minimize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: '{}'
      });
      const data = await res.json().catch(() => ({}));
      if (data && data.success === false) {
        console.warn('Desktop minimize call indicated failure:', data);
        setTimeout(restoreScreen, 300);
        return;
      }
    } catch (e) {
      console.warn('Desktop minimize call failed:', e);
      setTimeout(restoreScreen, 300);
      return;
    }

    // Safety fallback: if after 3.5s the window is still visible and focused,
    // restore smoothly so the user isn't stuck with a blank screen
    setTimeout(() => {
      if (!document.hidden) {
        restoreScreen();
      }
    }, 3500);
  });

  window.addEventListener('focus', () => {
    restoreScreen();
  });

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) {
      restoreScreen();
    }
  });
}

// Export Chat to Markdown
const exportChatBtn = document.getElementById('exportChatBtn');
if (exportChatBtn) {
  exportChatBtn.addEventListener('click', () => {
    if (conversationHistory.length === 0) {
      alert('No messages in current conversation to export.');
      return;
    }

    let md = `# NexusRoute Chat Export\n*Generated on: ${new Date().toLocaleString()}*\n\n---\n\n`;
    for (const msg of conversationHistory) {
      const roleName = msg.role === 'user' ? 'User' : 'Assistant (NexusRoute)';
      let textContent = '';
      if (typeof msg.content === 'string') {
        textContent = msg.content;
      } else if (Array.isArray(msg.content)) {
        textContent = msg.content.map(c => ('text' in c ? c.text : '[Attached Image]')).join('\n');
      }
      md += `### 👤 ${roleName}\n\n${textContent}\n\n---\n\n`;
    }

    const blob = new Blob([md], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nexusroute_chat_${Date.now()}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  });
}

// ==========================================================================
// Standalone Local AI Engine & Model Hub Manager
// ==========================================================================
const localHubModal = document.getElementById('localHubModal');
const openLocalHubModalBtn = document.getElementById('openLocalHubModalBtn');
const closeLocalHubModalBtn = document.getElementById('closeLocalHubModalBtn');
const localHubDoneBtn = document.getElementById('localHubDoneBtn');
const refreshLocalModelsBtn = document.getElementById('refreshLocalModelsBtn');
const unloadGpuModelsBtn = document.getElementById('unloadGpuModelsBtn');
const startPullModelBtn = document.getElementById('startPullModelBtn');
const pullModelInput = document.getElementById('pullModelInput');
const pullProgressContainer = document.getElementById('pullProgressContainer');
const pullStatusLabel = document.getElementById('pullStatusLabel');
const pullPercentLabel = document.getElementById('pullPercentLabel');
const pullProgressBar = document.getElementById('pullProgressBar');
const localModelsTableBody = document.getElementById('localModelsTableBody');
const installedModelsCount = document.getElementById('installedModelsCount');
const localEngineStatusDot = document.getElementById('localEngineStatusDot');
const localEngineStatusText = document.getElementById('localEngineStatusText');
const localEngineDetailsText = document.getElementById('localEngineDetailsText');

async function fetchLocalHubStatus() {
  try {
    const res = await fetch('/v1/local/status');
    if (!res.ok) throw new Error('Status request failed');
    const data = await res.json();
    if (localEngineStatusDot) {
      localEngineStatusDot.style.background = data.running ? '#22c55e' : '#ef4444';
    }
    if (localEngineStatusText) {
      localEngineStatusText.textContent = data.running
        ? (data.embedded ? '🚀 Standalone Portable Engine (Active)' : '⚡ System Local Engine (Active)')
        : '⚠️ Engine Inactive (Spawning on demand)';
    }
    if (localEngineDetailsText) {
      localEngineDetailsText.textContent = `GPU: ${data.gpuName || 'RTX 4060'} · CUDA 12 · Models: ${data.modelsCount || 0} (${data.modelsPath})`;
    }
    return data;
  } catch (err) {
    if (localEngineStatusText) localEngineStatusText.textContent = 'Offline';
    return null;
  }
}

async function renderLocalHubModels() {
  if (!localModelsTableBody) return;
  localModelsTableBody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); padding: 16px;">Loading installed models...</td></tr>';
  
  try {
    const res = await fetch('/v1/local/models');
    const data = await res.json();
    const models = data.models || [];
    if (installedModelsCount) installedModelsCount.textContent = String(models.length);
    
    // Update Modelfile Studio Base Model dropdown (mfFromSelect)
    const mfFromSelect = document.getElementById('mfFromSelect');
    if (mfFromSelect) {
      const currentVal = mfFromSelect.value;
      mfFromSelect.innerHTML = '';
      
      const defaultOpt = document.createElement('option');
      defaultOpt.value = '';
      defaultOpt.textContent = '-- Choose Base Model --';
      mfFromSelect.appendChild(defaultOpt);

      if (models.length > 0) {
        const instGroup = document.createElement('optgroup');
        instGroup.label = '📦 Installed On Local GPU';
        for (const m of models) {
          const opt = document.createElement('option');
          opt.value = m.rawName || m.id;
          opt.textContent = `💻 ${m.rawName} (${m.sizeFormatted || m.sizeGb})`;
          instGroup.appendChild(opt);
        }
        mfFromSelect.appendChild(instGroup);
      }

      const libGroup = document.createElement('optgroup');
      libGroup.label = '🌟 Popular Base Models';
      const commonBases = [
        'qwen2.5-coder:7b',
        'llama3.2:3b',
        'dolphin-roaster:latest',
        'deepseek-r1:8b',
        'mistral:7b',
        'phi3.5:latest',
      ];
      for (const b of commonBases) {
        if (!models.some(m => m.rawName === b)) {
          const opt = document.createElement('option');
          opt.value = b;
          opt.textContent = `📥 ${b}`;
          libGroup.appendChild(opt);
        }
      }
      mfFromSelect.appendChild(libGroup);

      const customOpt = document.createElement('option');
      customOpt.value = '__custom__';
      customOpt.textContent = '✏️ Custom .GGUF File Path / HuggingFace ID...';
      mfFromSelect.appendChild(customOpt);

      if (currentVal && Array.from(mfFromSelect.options).some(o => o.value === currentVal)) {
        mfFromSelect.value = currentVal;
      } else if (models.length > 0) {
        mfFromSelect.value = models[0].rawName;
        const mfFromInputEl = document.getElementById('mfFromInput');
        if (mfFromInputEl) mfFromInputEl.value = models[0].rawName;
      }
      syncModelfileToRaw();
    }

    localModelsTableBody.innerHTML = '';
    for (const m of models) {
      const tr = document.createElement('tr');
      const quant = m.quantization || m.parameterSize || 'Standard';
      const lowerName = (m.rawName || m.id || '').toLowerCase();
      const isTopCoder = lowerName.includes('deepseek-coder') || lowerName.includes('starcoder') || lowerName.includes('llama3.1') || lowerName.includes('wizard-coder') || lowerName.includes('codellama');
      const goldStarBadge = isTopCoder 
        ? `<span class="model-badge" style="background: rgba(234, 179, 8, 0.15); border: 1px solid rgba(234, 179, 8, 0.5); color: #facc15; font-size: 11px; font-weight: 700; margin-left: 6px;" title="Top-Rated Offline Coding Model (100% GPU offload, zero lazy placeholders)">⭐ Verified Coder</span>` 
        : '';
      const rawModelName = m.rawName || m.id || '';
      const avatarUrl = getModelAvatar(rawModelName);
      const defaultEmoji = isTopCoder ? '💻' : (lowerName.includes('roast') ? '🔥' : (lowerName.includes('dolphin') ? '🐬' : '🤖'));
      const avatarEl = avatarUrl
        ? `<img src="${escapeHtml(avatarUrl)}" class="table-model-avatar" alt="Avatar" title="${escapeHtml(rawModelName)}">`
        : `<div style="width:28px; height:28px; border-radius:50%; background:rgba(255,255,255,0.05); border:1px solid var(--border-subtle); display:flex; align-items:center; justify-content:center; font-size:13px; flex-shrink:0;">${defaultEmoji}</div>`;

      tr.innerHTML = `
        <td>
          <div style="display: flex; align-items: center; gap: 8px;">
            ${avatarEl}
            <div>
              <div style="font-weight: 600; color: var(--text-primary); font-family: monospace; display: flex; align-items: center; flex-wrap: wrap; gap: 4px;">
                ${escapeHtml(rawModelName)}
                ${goldStarBadge}
              </div>
              <div style="font-size: 11px; color: var(--text-muted);">${escapeHtml(m.family || 'llm')} · modified ${new Date(m.modifiedAt).toLocaleDateString()}</div>
            </div>
          </div>
        </td>
        <td><span style="font-weight: 500;">${escapeHtml(m.sizeFormatted || m.sizeGb || 'Unknown')}</span></td>
        <td><span class="model-badge" style="font-size: 11px;">${escapeHtml(quant)}</span></td>
        <td>
          <div style="display: flex; gap: 6px; flex-wrap: wrap;">
            <button class="action-tag-btn select-local-model-btn" data-model="local/${escapeHtml(m.rawName)}" style="color: var(--accent-cyan);" title="Select this model in chat">💬 Use in Chat</button>
            <button class="action-tag-btn edit-modelfile-btn" data-model="${escapeHtml(m.rawName)}" style="color: #a855f7;" title="Inspect and edit this model's Modelfile recipe">📝 Modelfile</button>
            <button class="action-tag-btn delete-local-model-btn" data-model="${escapeHtml(m.rawName)}" style="color: var(--accent-red);" title="Delete model from disk">🗑️</button>
          </div>
        </td>
      `;
      localModelsTableBody.appendChild(tr);
    }

    // Bind chat select buttons
    localModelsTableBody.querySelectorAll('.select-local-model-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const modelId = btn.getAttribute('data-model');
        if (modelSelect && modelId) {
          // Check if option exists or add it
          let opt = Array.from(modelSelect.options).find(o => o.value === modelId);
          if (!opt) {
            opt = document.createElement('option');
            opt.value = modelId;
            opt.textContent = `💻 ${modelId}`;
            modelSelect.appendChild(opt);
          }
          modelSelect.value = modelId;
          if (localHubModal) localHubModal.classList.add('hidden');
          const chatInput = document.getElementById('chatInput');
          if (chatInput) chatInput.focus();
        }
      });
    });

    // Bind edit modelfile buttons
    localModelsTableBody.querySelectorAll('.edit-modelfile-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const rawName = btn.getAttribute('data-model');
        if (!rawName) return;
        btn.textContent = 'Loading...';
        try {
          const sRes = await fetch('/v1/local/show', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: rawName }),
          });
          const sData = await sRes.json();
          if (sData.success) {
            const mfModelNameInput = document.getElementById('mfModelNameInput');
            const mfSystemPromptInput = document.getElementById('mfSystemPromptInput');
            const mfRawModelfileInput = document.getElementById('mfRawModelfileInput');
            const mfTempInput = document.getElementById('mfTempInput');
            const mfCtxInput = document.getElementById('mfCtxInput');
            const mfTopPInput = document.getElementById('mfTopPInput');

            if (mfModelNameInput) mfModelNameInput.value = `${rawName.replace(/:latest$/, '')}-custom`;
            setEffectiveFromModel(rawName);
            if (mfSystemPromptInput) mfSystemPromptInput.value = sData.system || '';
            if (mfRawModelfileInput) mfRawModelfileInput.value = sData.modelfile || '';
            
            if (sData.parameters) {
              const pStr = String(sData.parameters);
              const tempMatch = pStr.match(/temperature\s+([\d\.]+)/);
              if (tempMatch && mfTempInput) mfTempInput.value = tempMatch[1];
              const ctxMatch = pStr.match(/num_ctx\s+(\d+)/);
              if (ctxMatch && mfCtxInput) mfCtxInput.value = ctxMatch[1];
              const topPMatch = pStr.match(/top_p\s+([\d\.]+)/);
              if (topPMatch && mfTopPInput) mfTopPInput.value = topPMatch[1];
            }

            syncModelfileToRaw();
            const existingAvatar = getModelAvatar(rawName);
            if (existingAvatar) {
              setStudioAvatarPreview(existingAvatar);
              if (mfAvatarStatus) {
                mfAvatarStatus.textContent = `✅ Loaded avatar for ${rawName}`;
                mfAvatarStatus.style.color = '#22c55e';
              }
            } else {
              clearStudioAvatarPreview();
            }
            const studioEl = document.getElementById('mfModelNameInput');
            if (studioEl) studioEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
          } else {
            alert('Could not inspect model: ' + (sData.error || 'Unknown error'));
          }
        } catch (e) {
          alert('Error fetching modelfile: ' + e.message);
        } finally {
          btn.textContent = '📝 Modelfile';
        }
      });
    });

    // Bind delete buttons
    localModelsTableBody.querySelectorAll('.delete-local-model-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const modelName = btn.getAttribute('data-model');
        if (!modelName) return;
        if (!confirm(`Are you sure you want to permanently delete local model "${modelName}" from your disk?`)) return;
        btn.textContent = 'Deleting...';
        try {
          const dRes = await fetch('/v1/local/models', {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: modelName }),
          });
          const dData = await dRes.json();
          if (dData.success) {
            deleteModelAvatar(modelName);
            await renderLocalHubModels();
            await fetchLocalHubStatus();
            fetchModels();
          } else {
            alert('Delete failed: ' + dData.message);
          }
        } catch (e) {
          alert('Delete error: ' + e.message);
        }
      });
    });
  } catch (err) {
    localModelsTableBody.innerHTML = `<tr><td colspan="4" style="color: var(--accent-red); padding: 14px;">Error loading local models: ${escapeHtml(err.message)}</td></tr>`;
  }
}

